def lm_endpoint(alias,task,split):
 archive_split='test' if split=='test_exploratory' else split;root=A6/'lm'/alias/task/archive_split;expected=next(u for u in read(C6/'LM_INDEX.json')['units'] if (u['candidate'],u['task'],u['split'])==(alias,task,archive_split));require(sha(root/'COMPLETE.json')==expected['receipt_sha256'],'LM receipt identity mismatch');receipt=read(root/'COMPLETE.json');require(receipt['status']=='VERIFIED','LM endpoint not released');validate_members(root,receipt)
